-- SP-GiST inet_ops loses rows: an index over these 270 inet values (IPv4
-- and IPv6 mixed), inserted in this order, answers "ip <<= '2001:db8::/120'"
-- with 0 rows where a sequential scan finds 2.  GiST and B-tree indexes on
-- the same rows agree with the scan.  Found by bench/rebuild --move, whose
-- row-at-a-time apply lays rows out in this order; plain COPY and CREATE
-- INDEX reproduce it with nothing of ours involved.
--   psql -X -f spgist_inet_repro.sql
DROP TABLE IF EXISTS spgist_inet_repro;
CREATE TABLE spgist_inet_repro (ip inet);
CREATE INDEX spgist_inet_repro_sp ON spgist_inet_repro USING spgist (ip);
SET enable_seqscan = off;
SET enable_bitmapscan = off;
SET enable_indexonlyscan = off;
SELECT 'spgist index' AS via, count(*) FROM spgist_inet_repro WHERE ip <<= '2001:db8::/120';
SET enable_seqscan = on;
SET enable_indexscan = off;
SELECT 'sequential scan' AS via, count(*) FROM spgist_inet_repro WHERE ip <<= '2001:db8::/120';
DROP TABLE spgist_inet_repro;
